import re

def word_report(text, top_n=3):
    words = [w for w in re.findall(r"[a-zA-Z']+", text.lower()) if len(w) > 2]
    counter = {}
    for w in words:
        counter[w] = counter.get(w, 0) + 1
    ranked = sorted(counter.items(), key=lambda kv: (-kv[1], kv[0]))[:top_n]
    lines = [f'单词总数: {len(words)}', f'不重复单词: {len(counter)}', f'TOP {top_n}:']
    for i, (word, count) in enumerate(ranked, 1):
        lines.append(f'{i}. {word} ({count} 次)')
    return '\n'.join(lines)


