def parse_story(text):
    empty = {'role': '', 'feature': '', 'value': '', 'valid': False}
    if not isinstance(text, str) or not text.strip():
        return dict(empty)
    cleaned = text.strip().rstrip('。.')
    result = dict(empty)
    for key, marker in (('role', '作为'), ('feature', '我想要'), ('value', '以便')):
        if marker not in cleaned:
            continue
        tail = cleaned.split(marker, 1)[1]
        for other in ('作为', '我想要', '以便'):
            if other != marker and other in tail:
                tail = tail.split(other, 1)[0]
        result[key] = tail.strip().strip('，,。 ')
    result['valid'] = all(result[k] for k in ('role', 'feature', 'value'))
    return result


def check_acceptance(items):
    weak = []
    for item in items:
        text = str(item)
        has_number = any(ch.isdigit() for ch in text)
        has_result = any(word in text for word in ('能', '可以', '显示', '返回'))
        if not (has_number or has_result):
            weak.append(item)
    return weak


