import re

TYPES = ['feat', 'fix', 'docs', 'style', 'refactor', 'test', 'chore']
PATTERN = re.compile(r'^(?P<type>[a-z]+)(?:\((?P<scope>[^)]+)\))?: (?P<desc>.+)$')


def check_commit(message):
    problems = []
    if not isinstance(message, str) or not message.strip():
        return ['提交信息不能为空']
    text = message.strip()
    if len(text.splitlines()) > 1:
        problems.append('第一行应该是简短描述，详细说明放到空行之后')
        text = text.splitlines()[0]
    match = PATTERN.match(text)
    if not match:
        if ':' not in text:
            problems.append('缺少「类型: 描述」的结构')
        elif ': ' not in text and ':' in text:
            problems.append('冒号后面要有一个空格')
        else:
            problems.append('格式不符合「类型(范围): 描述」的约定')
        return problems
    if match.group('type') not in TYPES:
        problems.append('类型 ' + match.group('type') + ' 不在允许列表里：' + '/'.join(TYPES))
    desc = match.group('desc').strip()
    if len(desc) < 4:
        problems.append('描述太短（至少要 4 个字）')
    if len(desc) > 50:
        problems.append('描述太长（最多 50 个字）')
    if desc.endswith(('。', '.')):
        problems.append('描述结尾不要加句号')
    return problems


def split_commit(message):
    if check_commit(message):
        return None
    match = PATTERN.match(str(message).strip().splitlines()[0])
    return {
        'type': match.group('type'),
        'scope': match.group('scope') or '',
        'desc': match.group('desc').strip(),
    }


