imports = [('repositories', 'models'), ('services', 'repositories'),
           ('services', 'models'), ('controllers', 'services'),
           ('models', 'services')]


def check_layers(modules, imports):
    bad = []
    for source, target in imports:
        a = modules.get(source)
        b = modules.get(target)
        if a is None or b is None:
            continue
        if a < b:
            bad.append(f'{source} -> {target}（第 {a} 层依赖第 {b} 层，方向反了）')
    return bad


def topological_order(modules, imports):
    deps = {name: set() for name in modules}
    for source, target in imports:
        if source in deps and target in deps and source != target:
            deps[source].add(target)
    order = []
    remaining = set(deps)
    while remaining:
        ready = sorted(n for n in remaining if not (deps[n] & remaining))
        if not ready:
            return None
        order.extend(ready)
        remaining -= set(ready)
    return order


print(check_layers(modules, imports))
print(topological_order(modules, imports))

