import re

IDENT_RE = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')


def build_query(table, filters, order_by=None, limit=None):
    if not IDENT_RE.match(str(table or '')):
        raise ValueError('表名不合法')
    clauses = []
    params = []
    for column, value in (filters or {}).items():
        if value is None:
            continue
        if not IDENT_RE.match(str(column)):
            raise ValueError('字段名不合法')
        if isinstance(value, (list, tuple)):
            if not value:
                clauses.append(f'{column} IN (NULL)')
                continue
            placeholders = ', '.join('?' for _ in value)
            clauses.append(f'{column} IN ({placeholders})')
            params.extend(value)
        else:
            clauses.append(f'{column} = ?')
            params.append(value)
    sql = 'SELECT * FROM ' + str(table)
    if clauses:
        sql += ' WHERE ' + ' AND '.join(clauses)
    if order_by:
        desc = str(order_by).startswith('-')
        column = str(order_by).lstrip('-')
        if not IDENT_RE.match(column):
            raise ValueError('排序字段不合法')
        sql += f' ORDER BY {column} {"DESC" if desc else "ASC"}'
    if isinstance(limit, int) and not isinstance(limit, bool) and limit > 0:
        sql += ' LIMIT ?'
        params.append(limit)
    return sql, params


print(build_query('users', {'age': 18, 'city': '杭州', 'name': None}))
print(build_query('users', {'id': [1, 2, 3]}, order_by='-created_at', limit=5))
