def collect_updates(watchers, changed):
    changed_set = set(changed or [])
    dirty = []
    for component, deps in watchers.items():
        if changed_set & set(deps):
            dirty.append(component)
    return sorted(dirty)


def diff_state(old, new):
    old = old or {}
    new = new or {}
    changed = [k for k in new if k not in old or old[k] != new[k]]
    removed = [k for k in old if k not in new]
    return sorted(changed), sorted(removed)


def render_log(watchers, old, new):
    changed, removed = diff_state(old, new)
    dirty = collect_updates(watchers, changed)
    lines = [f'变化字段：{changed}', f'删除字段：{removed}',
             f'需要重渲染：{dirty}']
    return '\n'.join(lines)


