import inspect

_REGISTRY = {}


def tool(name, description):
    def decorator(func):
        params = list(inspect.signature(func).parameters.keys())
        _REGISTRY[name] = {'name': name, 'description': description,
                           'params': params, 'func': func}
        func._tool_name = name
        return func
    return decorator


def list_tools():
    return [{'name': entry['name'], 'description': entry['description'],
             'params': entry['params']} for _, entry in sorted(_REGISTRY.items())]


def call_tool(name, **kwargs):
    entry = _REGISTRY.get(name)
    if entry is None:
        return {'error': f'未知工具 {name}'}
    expected = set(entry['params'])
    given = set(kwargs)
    missing = expected - given
    unexpected = given - expected
    if missing or unexpected:
        parts = []
        if missing:
            parts.append('缺少参数 ' + ', '.join(sorted(missing)))
        if unexpected:
            parts.append('多余参数 ' + ', '.join(sorted(unexpected)))
        return {'error': '参数不匹配：' + '；'.join(parts)}
    try:
        return entry['func'](**kwargs)
    except Exception as exc:
        return {'error': f'执行失败：{type(exc).__name__} {exc}'}


@tool('get_weather', '查询某个城市的天气')
def get_weather(city):
    data = {'杭州': '晴 26℃', '上海': '多云 24℃'}
    if city not in data:
        raise KeyError(f'没有 {city} 的天气数据')
    return {'city': city, 'weather': data[city]}


@tool('add', '把两个数字相加')
def add(a, b):
    return a + b


