    {'id': 'T3', 'title': '实现用户接口', 'deps': ['T1', 'T2'], 'days': 2, 'priority': 1},
    {'id': 'T4', 'title': '接入 DeepSeek', 'deps': ['T3'], 'days': 2, 'priority': 1},
