def retry_call(fn, attempts=3, base_delay=0.5, max_delay=8.0, sleep=None):
    sleeper = sleep or time.sleep
    delays = []
    last_error = None
    for round_index in range(max(1, attempts)):
        try:
            return fn(), delays
        except RetryableError as exc:
            last_error = exc
            if round_index == attempts - 1:
                break
            delay = min(max_delay, base_delay * (2 ** round_index))
            delays.append(delay)
            sleeper(delay)
    raise last_error


