from collections import deque

def shortest_distance(edges, n, start, target):
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)
    if start == target:
        return 0
    distance = [-1] * n
    distance[start] = 0
    queue = deque([start])
    while queue:
        node = queue.popleft()
        for nxt in graph[node]:
            if distance[nxt] == -1:
                distance[nxt] = distance[node] + 1
                if nxt == target:
                    return distance[nxt]
                queue.append(nxt)
    return -1

