solution:
class LinearProbeHash:
    def __init__(self, size):
        self.size = size
        self.table = [None] * size

    def insert(self, key):
        start = key % self.size
        for step in range(self.size):
            slot = (start + step) % self.size
            if self.table[slot] is None:
                self.table[slot] = key
                return True
            if self.table[slot] == key:
                return False
        return False

    def search(self, key):
        start = key % self.size
        for step in range(self.size):
            cell = self.table[(start + step) % self.size]
            if cell is None:
                return False
            if cell == key:
                return True
        return False

    def probes(self, key):
        start = key % self.size
        for step in range(self.size):
            cell = self.table[(start + step) % self.size]
            if cell is None or cell == key:
                return step + 1
        return self.size

