def reverse_words(s):
    words = []
    current = ''
    for ch in str(s or ''):
        if ch == ' ':
            if current:
                words.append(current)
                current = ''
        else:
            current += ch
    if current:
        words.append(current)
    return ' '.join(reversed(words))


