def num_distinct(s, t):
    source = str(s or '')
    target = str(t or '')
    n, m = len(source), len(target)
    if m == 0:
        return 1
    if n < m:
        return 0
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][0] = 1
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if source[i - 1] == target[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j]
            else:
                dp[i][j] = dp[i - 1][j]
    return dp[n][m]


