print(spiral_order([[1, 2, 3, 4]]))

def merge_intervals(intervals):
    items = [list(pair) for pair in (intervals or [])]
    if not items:
        return []
    items.sort(key=lambda pair: (pair[0], pair[1]))
    merged = [items[0]]
    for start, end in items[1:]:
        last = merged[-1]
        if start <= last[1]:
            last[1] = max(last[1], end)
        else:
            merged.append([start, end])
    return merged


