def rotate_image(matrix):
    if not matrix or not matrix[0]:
        return matrix
    n = len(matrix)
    # 第一步：转置（只处理上三角，否则会交换两次等于没换）
    for i in range(n):
        for j in range(i + 1, n):
            matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]
    # 第二步：每行左右翻转
    for row in matrix:
        row.reverse()
    return matrix


